    "generic": "Gliclazide",
    "manufacturer": "Opsonin Pharma Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet (Modified Release)",
    "batch": "BT-20689-35",
    "packSize": "Unit Price: ৳ 11.00,(30's pack: ৳ 330.00),",
