    "id": "MED-B6105",
    "name": "Desolon 0.03 mg+0.15 mg",
    "generic": "Ethinyl Estradiol + Desogestrel (0.03 mg)",
    "manufacturer": "Renata Limited",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-6105-19",
    "packSize": "21 tablet pack: ৳ 105.00",
    "wholesalePrice": 86.1,
    "mrp": 105,
