    "id": "MED-B19553",
    "name": "Aristen 1%",
    "generic": "Clotrimazole (Topical)",
    "manufacturer": "Aristopharma Ltd.",
    "category": "Dermatology",
    "dosageForm": "Cream",
    "batch": "BT-19553-46",
