    "generic": "Linezolid",
    "manufacturer": "Incepta Pharmaceuticals Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-8933-77",
    "packSize": "Unit Price: ৳ 85.00,(10's pack: ৳ 850.00),",
    "wholesalePrice": 69.7,
