    "id": "MED-B31551",
    "name": "Mavira 200 mg",
    "generic": "Molnupiravir",
    "manufacturer": "Drug International Ltd.",
    "category": "Antibiotics",
    "dosageForm": "Capsule",
    "batch": "BT-31551-48",
    "packSize": "Unit Price: ৳ 50.00,(40's pack: ৳ 2,000.00),",
    "wholesalePrice": 41,
