    "id": "MED-B6387",
    "name": "Sinaflox 250 mg",
    "generic": "Flucloxacillin Sodium",
    "manufacturer": "Ibn Sina Pharmaceuticals Ltd.",
    "category": "Antibiotics",
    "dosageForm": "Capsule",
    "batch": "BT-6387-63",
