    "id": "MED-B26103",
    "name": "Formocort 400 mcg+12 mcg",
    "generic": "Budesonide + Formoterol Fumarate",
    "manufacturer": "Healthcare Pharmaceuticals Ltd.",
    "category": "Antibiotics",
    "dosageForm": "Inhalation Capsule",
    "batch": "BT-26103-17",
