    "name": "Rozith 500 mg",
    "generic": "Azithromycin Dihydrate",
    "manufacturer": "Healthcare Pharmaceuticals Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-8688-64",
    "packSize": "Unit Price: ৳ 35.00,(12's pack: ৳ 420.00),",
    "wholesalePrice": 28.7,
