    "id": "MED-B11258",
    "name": "Recox 60 mg",
    "generic": "Etoricoxib",
    "manufacturer": "Renata Limited",
    "category": "Pain Relief",
    "dosageForm": "Tablet",
    "batch": "BT-11258-30",
    "packSize": "Unit Price: ৳ 7.00,(30's pack: ৳ 210.00),",
    "wholesalePrice": 5.74,
