    "category": "Antibiotics",
    "dosageForm": "Capsule",
    "batch": "BT-33009-67",
    "packSize": "Unit Price: ৳ 30.00,(30's pack: ৳ 900.00),",
    "wholesalePrice": 24.6,
    "mrp": 30,
