    "generic": "Vitamin C [Ascorbic acid]",
    "manufacturer": "Beximco Pharmaceuticals Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Chewable Tablet",
    "batch": "BT-13903-41",
    "packSize": "Unit Price: ৳ 1.90,(200's pack: ৳ 380.00),",
    "wholesalePrice": 1.56,
    "mrp": 1.9,
