    "id": "MED-B29289",
    "name": "Angela 1 mg+0.5 mg",
    "generic": "Ethinyl Estradiol + Drospirenone (HRT)",
    "manufacturer": "Renata Limited",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-29289-97",
    "packSize": "Unit Price: ৳ 24.00,(28's pack: ৳ 672.00),",
    "wholesalePrice": 19.68,
    "mrp": 24,
