    "id": "MED-B6389",
    "name": "Sinaflox 125 mg/5 ml",
    "generic": "Flucloxacillin Sodium",
    "manufacturer": "Ibn Sina Pharmaceuticals Ltd.",
    "category": "Antibiotics",
    "dosageForm": "Powder for Suspension",
    "batch": "BT-6389-44",
    "packSize": "100 ml bottle: ৳ 65.00",
    "wholesalePrice": 53.3,
