    "id": "MED-B32842",
    "name": "Miraclon 1 mg",
    "generic": "Clonazepam",
    "manufacturer": "Beacon Pharmaceuticals Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-32842-22",
