    "id": "MED-B14980",
    "name": "Joinix Plus 250 mg+200 mg",
    "generic": "Glucosamine Sulfate + Chondroitin",
    "manufacturer": "Incepta Pharmaceuticals Ltd.",
    "category": "Gastrointestinal",
    "dosageForm": "Tablet",
    "batch": "BT-14980-29",
